#!/usr/bin/env node
/**
 * Write examples/licences.js from whatever licence keys this machine has.
 *
 * Four players in the inventory are commercial and need a key before they will play
 * anything: JW Player, THEOplayer, Bitmovin and Flowplayer. Their libraries still
 * load and construct without one, which is enough to check a binding against the real
 * API surface, so the example page mounts them either way and says which mode it is in.
 *
 * Keys are read from the environment, or from a gitignored licences.env beside this
 * repo, and are never committed. The generated file is gitignored too. Absent keys
 * produce an empty object rather than an error: the page and the e2e run both have to
 * work on a machine that has none, which is every CI runner.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));

/** Environment name to the key the page reads. */
const KEYS = {
  BITMOVIN_KEY: 'bitmovin',
  THEOPLAYER_LICENSE: 'theoplayer',
  FLOWPLAYER_TOKEN: 'flowplayer',
  // Either a key or a full https://cdn.jwplayer.com/libraries/<id>.js URL. JW has no
  // public npm package, so without this there is no library to load at all.
  JWPLAYER_LIBRARY: 'jwplayer',
};

async function fromFile() {
  const path = process.env.PLAYER_LICENCES_FILE ?? join(root, 'licences.env');
  let text;
  try {
    text = await readFile(path, 'utf8');
  } catch {
    return {};
  }
  const out = {};
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq < 0) continue;
    out[trimmed.slice(0, eq).trim()] = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, '');
  }
  return out;
}

const file = await fromFile();
const licences = {};
for (const [env, name] of Object.entries(KEYS)) {
  const value = process.env[env] || file[env];
  if (value) licences[name] = value;
}

const names = Object.keys(licences);
await writeFile(
  join(root, 'examples', 'licences.js'),
  `// Generated by scripts/make-licences.mjs. Gitignored. Do not commit.\n` +
    `window.__LICENCES = ${JSON.stringify(licences, null, 2)};\n`,
);
console.log(
  names.length ? `licences present: ${names.join(', ')}` : 'no licences, running unlicensed',
);
